/**
 * Legacy Html5Qrcode Compatibility Layer -> HMS Production Fullscreen Scanner
 */
(function (global) {
  'use strict';

  function Html5Qrcode(elementId) {
    this.elementId = elementId;
  }

  Html5Qrcode.prototype.start = function (cameraConfig, configuration, onScanSuccess, onScanError) {
    if (global.HMSQRScanner) {
      return new Promise((resolve, reject) => {
        global.HMSQRScanner.open({
          title: 'Outpass QR Scanner',
          mainText: 'Align the QR code inside the frame',
          subText: 'The QR will be scanned automatically.',
          allowManual: true,
          onScan: (data) => {
            if (typeof onScanSuccess === 'function') {
              onScanSuccess(data);
            }
          },
          onClose: () => {
            if (typeof onScanError === 'function') {
              onScanError('Scanner closed by user');
            }
          }
        });
        resolve();
      });
    }
    return Promise.reject('HMSQRScanner engine not loaded');
  };

  Html5Qrcode.prototype.stop = function () {
    if (global.HMSQRScanner) {
      global.HMSQRScanner.close();
    }
    return Promise.resolve();
  };

  Html5Qrcode.prototype.clear = function () {
    if (global.HMSQRScanner) {
      global.HMSQRScanner.close();
    }
    return Promise.resolve();
  };

  Html5Qrcode.prototype.applyVideoConstraints = function (constraints) {
    if (global.HMSQRScanner && constraints && constraints.advanced && constraints.advanced[0]) {
      if (constraints.advanced[0].torch !== undefined) {
        global.HMSQRScanner.toggleTorch();
      }
    }
    return Promise.resolve();
  };

  global.Html5Qrcode = Html5Qrcode;
})(typeof self !== 'undefined' ? self : this);
